const payload = $json.body && typeof $json.body === "object" ? $json.body : $json;
const inputTokens = Number(payload.input_tokens ?? 0);
const promptTokens = Number(payload.prompt_tokens ?? inputTokens);
const attachmentTokens = Number(payload.attachment_tokens ?? 0);
const safePrompt = typeof payload.prompt === "string" ? payload.prompt.trim() : "";
const model = typeof payload.model === "string" ? payload.model.trim() : "";
const intent = typeof payload.intent === "string" ? payload.intent.trim() : "Chat";
const outputGoalTypes = ["Chat", "Agent", "App", "Website", "MCP", "Report/Document", "Image", "Video", "Audiobook"];
const outputType = typeof payload.output_type === "string" && outputGoalTypes.includes(payload.output_type.trim())
  ? payload.output_type.trim()
  : (outputGoalTypes.includes(intent) ? intent : "Chat");
const attachments = Array.isArray(payload.input_attachments)
  ? payload.input_attachments.map((attachment) => ({
      type: attachment.type,
      name: attachment.name,
      size_bytes: Number(attachment.size_bytes ?? 0),
      pages: Number(attachment.pages ?? 0),
      width: Number(attachment.width ?? 0),
      height: Number(attachment.height ?? 0),
      token_estimate: Number(attachment.token_estimate ?? 0),
      confidence: attachment.confidence || "unknown",
      method: attachment.method || "unknown"
    }))
  : [];
const attachmentSummary = attachments.length
  ? attachments.map((attachment) => {
      const dimensions = attachment.width && attachment.height
        ? ", " + attachment.width + "x" + attachment.height
        : "";
      const pages = attachment.pages ? ", " + attachment.pages + " pages" : "";
      return attachment.type + ": " + attachment.name + dimensions + pages + ", " + attachment.token_estimate + " tokens, " + attachment.confidence + " confidence";
    }).join("; ")
  : "none";

return [{
  ...payload,
  input_tokens: inputTokens,
  prompt_tokens: promptTokens,
  attachment_tokens: attachmentTokens,
  input_attachments: attachments,
  output_type: outputType,
  model,
  estimator_model: "openrouter/free",
  intent: outputType,
  input_price: Number(payload.input_price ?? 0),
  output_price: Number(payload.output_price ?? 0),
  openrouter_request: {
    model: "openrouter/free",
    temperature: 0.1,
    max_tokens: 500,
    provider: {
      require_parameters: true
    },
    response_format: {
      type: "json_schema",
      json_schema: {
        name: "token_optimizer_estimate",
        strict: true,
        schema: {
          type: "object",
          properties: {
            predicted_output: { type: "integer", minimum: 0 },
            predicted_output_min: { type: "integer", minimum: 0 },
            predicted_output_max: { type: "integer", minimum: 0 },
            prediction_confidence: { type: "number", minimum: 0, maximum: 1 },
            optimization_tip: { type: "string" }
          },
          required: ["predicted_output", "predicted_output_min", "predicted_output_max", "prediction_confidence", "optimization_tip"],
          additionalProperties: false
        }
      }
    },
    plugins: [{ id: "response-healing" }],
    messages: [
      {
        role: "system",
        content: "You estimate usage for TokenOptimizer. Treat output_type as the authoritative output goal and never override it from prompt keywords. Chat, Agent, App, Website, MCP, and Report/Document are text artifacts, so estimate realistic output tokens and min/max bounds for the artifact shape. Agent should account for workflow/tool instructions, App for implementation or product planning, Website for page/content structure, MCP for protocol/server details, and Report/Document for sectioned long-form deliverables. For Image, Video, and Audiobook outputs, predicted_output tokens must be 0 because output cost is modality based. Return only valid JSON matching the schema. optimization_tip must explain the best cost-saving prompt/model strategy for the selected output_type."
      },
      {
        role: "user",
        content: "Target model for pricing: " + model + "\nOutput goal: " + outputType + "\nInput tokens: " + inputTokens + "\nPrompt tokens: " + promptTokens + "\nAttachment tokens: " + attachmentTokens + "\nAttachment summary: " + attachmentSummary + "\nPrompt:\n" + safePrompt
      }
    ]
  }
}];

const requestPayload = $node["Build Estimator Request"].json;
const raw = $json.choices?.[0]?.message?.content ?? "";
const cleaned = String(raw)
  .replace(/\`\`\`json/g, "")
  .replace(/\`\`\`/g, "")
  .trim();

const inputTokens = Number(requestPayload.input_tokens ?? 0);
const outputType = requestPayload.output_type || "Chat";
const isMediaOutput = ["Image", "Video", "Audiobook"].includes(outputType);
const isDocumentOutput = outputType === "Report/Document";
const isStructuredTextOutput = ["Agent", "App", "Website", "MCP"].includes(outputType);
const heuristicMultiplier = isDocumentOutput ? 1.8 : isStructuredTextOutput ? 1.5 : 1.2;
const heuristicMinimum = isDocumentOutput ? 900 : isStructuredTextOutput ? 600 : 256;
const heuristicPrediction = isMediaOutput ? 0 : Math.max(Math.ceil(inputTokens * heuristicMultiplier), heuristicMinimum);
const upstreamError = $json.error?.message || $json.error || $json.message || "";

function parseEstimatorJson(value) {
  if (!value) {
    return null;
  }

  try {
    return JSON.parse(value);
  } catch (error) {
    const start = value.indexOf("{");
    const end = value.lastIndexOf("}");

    if (start === -1 || end === -1 || end <= start) {
      return null;
    }

    try {
      return JSON.parse(value.slice(start, end + 1));
    } catch {
      return null;
    }
  }
}

const parsed = parseEstimatorJson(cleaned);
const predictedOutput = Number(parsed?.predicted_output);
const predictedMin = Number(parsed?.predicted_output_min);
const predictedMax = Number(parsed?.predicted_output_max);
const confidence = Number(parsed?.prediction_confidence);
let optimizationTip = typeof parsed?.optimization_tip === "string" && parsed.optimization_tip.trim()
  ? parsed.optimization_tip.trim()
  : "";

if (!optimizationTip) {
  if (upstreamError) {
    optimizationTip = "OpenRouter estimator was unavailable: " + String(upstreamError).slice(0, 180);
  } else if (cleaned) {
    optimizationTip = cleaned.replace(/\s+/g, " ").slice(0, 220);
  } else if (isMediaOutput) {
    optimizationTip = "Use a modality-compatible model and keep prompt instructions focused on the selected output goal.";
  } else {
    optimizationTip = "Shorten repeated context, state the artifact shape, and choose the smallest model that can preserve required quality.";
  }
}

return [{
  input_tokens: inputTokens,
  prompt_tokens: Number(requestPayload.prompt_tokens ?? inputTokens),
  attachment_tokens: Number(requestPayload.attachment_tokens ?? 0),
  input_attachments: requestPayload.input_attachments ?? [],
  output_type: outputType,
  predicted_output: Number.isFinite(predictedOutput) && predictedOutput >= 0 ? Math.ceil(predictedOutput) : heuristicPrediction,
  predicted_output_min: Number.isFinite(predictedMin) && predictedMin >= 0 ? Math.ceil(predictedMin) : undefined,
  predicted_output_max: Number.isFinite(predictedMax) && predictedMax >= 0 ? Math.ceil(predictedMax) : undefined,
  prediction_confidence: Number.isFinite(confidence) ? confidence : undefined,
  optimization_tip: optimizationTip,
  intent: outputType,
  input_price: Number(requestPayload.input_price ?? 0),
  output_price: Number(requestPayload.output_price ?? 0)
}];

const inputCost = $json.input_tokens * ($json.input_price / 1000);
const outputCost = $json.predicted_output * ($json.output_price / 1000);

return [{
  input_tokens: $json.input_tokens,
  prompt_tokens: $json.prompt_tokens,
  attachment_tokens: $json.attachment_tokens,
  input_attachments: $json.input_attachments ?? [],
  output_type: $json.output_type,
  predicted_output: $json.predicted_output,
  predicted_output_min: $json.predicted_output_min,
  predicted_output_max: $json.predicted_output_max,
  estimated_cost: Number((inputCost + outputCost).toFixed(6)),
  optimization_tip: $json.optimization_tip,
  prediction_confidence: $json.prediction_confidence
}];
